export function normalizeNormanRollerFabricSearch(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

export function searchNormanRollerFabrics(
  query: string,
  options: { includeUnavailable?: boolean; limit?: number } = {},
): NormanRollerFabricColor[] {
  const normalized = normalizeNormanRollerFabricSearch(query);
  const limit = options.limit ?? 40;
  const sourceRows = options.includeUnavailable
    ? normanRollerFabricColors
    : normanRollerFabricColors.filter((row) => row.available);
  if (!normalized) return sourceRows.slice(0, limit);
  const parts = normalized.split(" ").filter(Boolean);
  return sourceRows.filter((row) => parts.every((part) => row.searchText.includes(part))).slice(0, limit);
}

export function findNormanRollerFabricColor(collection: string | null | undefined, colorCode: string | null | undefined): NormanRollerFabricColor | undefined {
  if (!collection || !colorCode) return undefined;
  const normalizedCollection = collection.trim().toLowerCase();
  const normalizedCode = colorCode.trim().toLowerCase();
  return normanRollerFabricColors.find(
    (row) => row.available && row.collection.toLowerCase() === normalizedCollection && row.colorCode.toLowerCase() === normalizedCode,
  );
}

export function normanRollerFabricLabel(row: Pick<NormanRollerFabricColor, "collection" | "colorCode" | "colorName">): string {
  return `${row.colorCode} - ${row.colorName} | ${row.collection}`;
}
